use verus::prelude::*;

#[requires(a.len() == b.len())]
#[ensures(result.len() == a.len())]
#[ensures(
    forall(|i: usize| i < a.len() ==> result[i] == (a[i] == b[i]))
)]
fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // It's assumed that `a.len() == b.len()`.
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x == y)
     .collect()
}

